// Deterministic hand-drawn path generators
function getHandDrawnRect(w: number, h: number, r: number, seed: string): string {
  const rnd = (s: string) => (random(`${seed}-${s}`) - 0.5) * 6; // +/- 3px variation

  const x0 = r + rnd("x0");
  const y0 = rnd("y0");
  const x1 = w - r + rnd("x1");
  const y1 = rnd("y1");

  const cx1 = w + rnd("cx1");
  const cy1 = rnd("cy1");
  const x2 = w + rnd("x2");
  const y2 = r + rnd("y2");

  const x3 = w + rnd("x3");
  const y3 = h - r + rnd("y3");

  const cx2 = w + rnd("cx2");
  const cy2 = h + rnd("cy2");
  const x4 = w - r + rnd("x4");
  const y4 = h + rnd("y4");

  const x5 = r + rnd("x5");
  const y5 = h + rnd("y5");

  const cx3 = rnd("cx3");
  const cy3 = h + rnd("cy3");
  const x6 = rnd("x6");
  const y6 = h - r + rnd("y6");

  const x7 = rnd("x7");
  const y7 = r + rnd("y7");

  const cx4 = rnd("cx4");
  const cy4 = rnd("cy4");

  // Mid points on edges to give organic slight curvatures
  const mxTop = w / 2 + rnd("mxTop");
  const myTop = rnd("myTop") * 1.5;

  const mxRight = w + rnd("mxRight") * 1.5;
  const myRight = h / 2 + rnd("myRight");

  const mxBottom = w / 2 + rnd("mxBottom");
  const myBottom = h + rnd("myBottom") * 1.5;

  const mxLeft = rnd("mxLeft") * 1.5;
  const myLeft = h / 2 + rnd("myLeft");

  return [
    `M ${x0},${y0}`,
    `Q ${mxTop},${myTop} ${x1},${y1}`,
    `Q ${cx1},${cy1} ${x2},${y2}`,
    `Q ${mxRight},${myRight} ${x3},${y3}`,
    `Q ${cx2},${cy2} ${x4},${y4}`,
    `Q ${mxBottom},${myBottom} ${x5},${y5}`,
    `Q ${cx3},${cy3} ${x6},${y6}`,
    `Q ${mxLeft},${myLeft} ${x7},${y7}`,
    `Q ${cx4},${cy4} ${x0},${y0}`,
  ].join(" ");
}

function getHandDrawnLine(xStart: number, yStart: number, xEnd: number, yEnd: number, seed: string): string {
  const rnd = (s: string) => (random(`${seed}-${s}`) - 0.5) * 4;
  const xMid = (xStart + xEnd) / 2 + rnd("xMid");
  const yMid = (yStart + yEnd) / 2 + rnd("yMid") * 2;
  return `M ${xStart},${yStart} Q ${xMid},${yMid} ${xEnd + rnd("xEnd")},${yEnd + rnd("yEnd")}`;
}

function getHandDrawnArrow(x1: number, y1: number, x2: number, y2: number, seed: string): string {
  const rnd = (s: string) => (random(`${seed}-${s}`) - 0.5) * 3;
  const xMid = (x1 + x2) / 2 + rnd("xMid");
  const yMid = (y1 + y2) / 2 + rnd("yMid");

  // Arrow line
  const line = `M ${x1},${y1} Q ${xMid},${yMid} ${x2},${y2}`;

  // Head: >
  const headSize = 14;
  const head1 = `M ${x2 - headSize},${y2 - headSize * 0.5 + rnd("h1")} Q ${x2 - headSize * 0.3},${y2 + rnd("h2")} ${x2},${y2}`;
  const head2 = `M ${x2 - headSize},${y2 + headSize * 0.5 + rnd("h3")} Q ${x2 - headSize * 0.3},${y2 + rnd("h4")} ${x2},${y2}`;

  return `${line} ${head1} ${head2}`;
}

// Scribble pattern generator to create hand-colored fills
const ScribblePattern: React.FC<{ id: string; color: string }> = ({ id, color }) => (
  <pattern id={id} width="16" height="16" patternUnits="userSpaceOnUse" patternTransform="rotate(40)">
    <line x1="0" y1="0" x2="0" y2="16" stroke={color} strokeWidth="3" opacity="0.75" strokeLinecap="round" />
    <line x1="0" y1="4" x2="16" y2="4" stroke={color} strokeWidth="1.5" opacity="0.45" strokeLinecap="round" />
  </pattern>
);

